function guideTextMatches(query,texts){const text=texts.filter(Boolean).join(' ').normalize('NFKC').toLocaleLowerCase();return query.normalize('NFKC').trim().toLocaleLowerCase().split(/\s+/).every(token=>text.includes(token));}
function guideMatchingWorks(query){if(!query)return [];return philosophyAtlasData.nodes.filter(n=>{if(n.kind!=='work')return false;const original=n.readRef&&typeof cultureEntity==='function'?cultureEntity(n.readRef.id):null;return guideTextMatches(query,[n.title,n.summary,...n.sections.map(s=>s.text),original?.originalTitle,...(original?.aliases||[]),...(n.personIds||[]).map(id=>guidePersonNode(id)?.title)]);}).sort((a,b)=>Number(b.title.toLocaleLowerCase().includes(query))-Number(a.title.toLocaleLowerCase().includes(query))||a.anchor-b.anchor);}
