function captureGuidePerson(){if(!guidePersonNode(guidePersonId))return null;return {id:guidePersonId,tab:guidePersonTab,scroll:$('#philosophy-person-dialog').scrollTop,details:[...$('#philosophy-person-content').querySelectorAll('details')].flatMap((e,index)=>e.open?[index]:[])};}
