function validGuideReading(value){return Boolean(value&&value.version===1&&typeof value.query==='string'&&value.query.length<=200&&philosophyAtlasData.phases.some(p=>p.id===value.era)&&Number.isFinite(value.offset)&&value.offset>=0&&value.offset<=100000&&(value.person===null||validGuideSnapshot(value.person)));}
